<?php
require_once __DIR__ . '/../includes/auth.php'; require_role(['teacher']); require __DIR__ . '/../config/database.php'; $pageTitle='Review Submissions'; $notice='';
if($_SERVER['REQUEST_METHOD']==='POST'){$sid=(int)($_POST['submission_id']??0);$score=$_POST['score']??'';$feedback=trim($_POST['feedback']??'');if(!is_numeric($score)||$score<0){$notice='Enter a valid non-negative score.';}else{$q=$pdo->prepare("UPDATE submissions sub JOIN activities a ON a.id=sub.activity_id SET sub.score=?,sub.feedback=?,sub.status='graded' WHERE sub.id=? AND a.created_by=?");$q->execute([(float)$score,$feedback,$sid,$_SESSION['user_id']]);$notice=$q->rowCount()?'Grade saved.':'No matching submission found.';}}
$q=$pdo->prepare('SELECT sub.id,sub.answer_text,sub.score,sub.feedback,sub.status,sub.submitted_at,a.title,u.full_name AS student_name,s.subject_name FROM submissions sub JOIN activities a ON a.id=sub.activity_id JOIN users u ON u.id=sub.student_id JOIN subjects s ON s.id=a.subject_id WHERE a.created_by=? ORDER BY sub.submitted_at DESC');$q->execute([$_SESSION['user_id']]);$rows=$q->fetchAll();require __DIR__ . '/../includes/header.php'; ?>
<?php if($notice): ?><div class="alert"><?= e($notice) ?></div><?php endif; ?><section class="panel"><div class="panel-head"><h3>Student submissions</h3></div><?php if(!$rows): ?><p class="empty">No submissions received yet.</p><?php endif; ?>
<?php foreach($rows as $r): ?><article class="activity-card"><h3><?= e($r['title']) ?></h3><p class="muted"><?= e($r['student_name']) ?> · <?= e($r['subject_name']) ?> · <?= e($r['submitted_at']) ?></p><div class="answer-box"><?= nl2br(e($r['answer_text'])) ?></div><form method="post" class="submit-form"><input type="hidden" name="submission_id" value="<?= (int)$r['id'] ?>"><label>Score</label><input type="number" name="score" min="0" step="0.01" required value="<?= e($r['score']??'') ?>"><label>Feedback</label><textarea name="feedback" rows="2"><?= e($r['feedback']??'') ?></textarea><button class="btn" type="submit">Save grade</button></form></article><?php endforeach; ?></section>
<?php require __DIR__ . '/../includes/footer.php'; ?>
